/*
 * A074203  Odd numbers k such that the number of 1's in the binary
 *          representation of k divides 2^k-1.
 * https://oeis.org/A074203
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 1373, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   powmod_2
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A074203: odd k such that the popcount(k) divides 2^k-1
 *
 *  The sequence is generated by testing successive odd integers,
 *  computing their popcount and verifying that 2^k ≡ 1 (mod popcount(k)).
 *  The first term (k = 1) is pre‑stated; subsequent terms are found
 *  in ascending order and cached for repeated queries.  The implementation
 *  uses only the C standard library and the provided integer types
 *  (seq_t and idx_t).  All arithmetic stays within the bounds of
 *  seq_t, and the exponent for 2^k is manipulated modulo φ(popcount(k)),
 *  avoiding large intermediate values.
 */
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/powmod_2.h"

seq_t a(idx_t n)
{
    /* cache of found terms (in ascending order) */
    static seq_t *cache      = NULL;
    static idx_t  cache_len  = 0;
    static idx_t  cache_cap  = 0;
    /* next odd candidate to test */
    static idx_t last_checked = 3;

    /* initialise cache on first call */
    if (cache == NULL) {
        cache_cap = 64;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        if (cache == NULL)
            return (seq_t)0;        /* allocation failed */
        cache[0] = (seq_t)1;        /* a(1) = 1 */
        cache_len = 1;
    }

    /* enlarge cache when needed */
    if (cache_len >= cache_cap) {
        cache_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
        if (tmp == NULL)
            return (seq_t)0;        /* allocation failed */
        cache = tmp;
    }

    /* generate terms until we have at least n terms */
    while (cache_len < n) {
        idx_t cand = last_checked;

        /* popcount of cand (cand fits in 64‑bit) */
        unsigned pc = __builtin_popcountll((unsigned long long)cand);

        /* 2^cand mod pc  (pc ≤ 64) */
        seq_t rem = powmod_2(cand, pc);

        /* condition: 2^cand ≡ 1 (mod popcount) */
        if (rem == (seq_t)1) {
            if (cache_len >= cache_cap) {
                cache_cap <<= 1;
                seq_t *tmp = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
                if (tmp == NULL)
                    return (seq_t)0;
                cache = tmp;
            }
            cache[cache_len++] = (seq_t)cand;
        }

        last_checked += 2;   /* next odd number */
    }

    return cache[n - 1];
}
